下面这段模拟「后端逐块产生、网关透传、客户端拼接」的代码，输出是什么？

```js
async function* backend() {
  for (const t of ["思考中…", "检索知识库", "生成：你好", "，我是助手"]) {
    await new Promise(r => setTimeout(r, 5));
    yield `data: ${t}\n\n`;
  }
}
async function gateway(src, sink) {
  for await (const c of src) sink.push(c);
}
(async () => {
  const out = [];
  await gateway(backend(), out);
  const events = out.join("").split("\n\n").filter(Boolean).map(e => e.replace(/^data: /, ""));
  console.log("转发块数:", out.length);
  console.log("客户端拼接:", events.join(""));
})();
```

下面的「创建任务」实现，在客户端断网重连时会新建第二个任务，导致同一个业务被跑两遍。指出问题并改正。

```js
async function createTask(userId, docId) {
  // 每次请求都新建一个 task，没有幂等键
  const id = "task_" + Math.random().toString(36).slice(2);
  await db.insert({ id, userId, docId, state: "queued" });
  return id;
}
```

