async function createTask(userId, docId) {
  const idemKey = `${userId}:${docId}`; // 业务幂等键
  const existing = await db.findByKey(idemKey);
  if (existing) return existing.id;     // 重复提交返回同一任务，不新建
  const id = "task_" + crypto.randomUUID();
  await db.insert({ id, idemKey, userId, docId, state: "queued" });
  return id;
}

const log = new Map();
let execCount = 0;
function callTool(callId, op) {
  if (log.has(callId)) return { out: log.get(callId), retried: true };
  execCount++;
  const out = `exec:${op}#${execCount}`;
  log.set(callId, out);
  return { out, retried: false };
}
console.log(JSON.stringify(callTool("c1", "search")));
console.log(JSON.stringify(callTool("c1", "search")));
console.log(JSON.stringify(callTool("c2", "search")));
console.log("实际执行次数:", execCount);

