下面的审计记录方式，事后无法发现某条记录被改过。指出问题并改正。

```js
function appendAudit(entry) {
  fs.appendFileSync("audit.log", JSON.stringify(entry) + "\n"); // 明文追加，无完整性校验
}
```

answer.reference_code:
const crypto = require("crypto");
function h(s) { return crypto.createHash("sha256").update(s).digest("hex"); }
const chain = [];
function appendAudit(entry) {
  const prev = chain.length ? chain[chain.length - 1].hash : "GENESIS";
  const hash = h(prev + "|" + JSON.stringify(entry));
  chain.push({ entry, prev, hash }); // 每条引用上一条的哈希
}
function verify() {
  for (let i = 0; i < chain.length; i++) {
    const prev = i ? chain[i - 1].hash : "GENESIS";
    if (h(prev + "|" + JSON.stringify(chain[i].entry)) !== chain[i].hash) return false;
  }
  return true;
}
